/**
 * Blog Data — 50 artigos profissionais sobre saúde/farmácia
 * SEO-ready: title tag, meta description, h1, h2, url amigável
 * Bilingual: PT (português) e EN (inglês)
 * Categorias: Regulatório, Inovação, Farmácia Clínica, Tecnologia, Gestão, Indústria
 */

export interface BlogPost {
  slug: string;
  date: string;
  readTime: string;
  category: string;
  seo: {
    titleTag: string;
    metaDescription: string;
    h1: string;
    h2: string[];
    url: string;
  };
  pt: {
    title: string;
    summary: string;
    content: string;
    source: string;
  };
  en: {
    title: string;
    summary: string;
    content: string;
    source: string;
  };
}

function post(
  slug: string,
  date: string,
  readTime: string,
  category: string,
  h2: string[],
  ptTitle: string,
  ptSummary: string,
  ptContent: string,
  enTitle: string,
  enSummary: string,
  enContent: string,
): BlogPost {
  const url = `https://www.thiagopiola.com.br/blog/${slug}`;
  // Extract source from end of content (last **Source:** or **Fonte:** line)
  const ptSourceMatch = ptContent.match(/\*\*[^*]+\*\*$/);
  const enSourceMatch = enContent.match(/\*\*[^*]+\*\*$/);
  const ptSource = ptSourceMatch ? ptSourceMatch[0] : '';
  const enSource = enSourceMatch ? enSourceMatch[0] : '';
  return {
    slug,
    date,
    readTime,
    category,
    seo: {
      titleTag: `${ptTitle} | Blog do Thiago Piola`,
      metaDescription: ptSummary.substring(0, 160),
      h1: ptTitle,
      h2,
      url,
    },
    pt: { title: ptTitle, summary: ptSummary, content: ptContent, source: ptSource },
    en: { title: enTitle, summary: enSummary, content: enContent, source: enSource },
  };
}

